const extractName = (text)=>{
    const t = text.trim();
    const patterns = [
        /my name is\s+(\w+)/i,
        /i(?:'m| am)\s+(\w+)/i,
        /call me\s+(\w+)/i
    ];
    for (const p of patterns){
        const m = t.match(p);
        if (m) return m[1].charAt(0).toUpperCase() + m[1].slice(1).toLowerCase();
    }
    const first = t.split(/\s+/)[0];
    return first.charAt(0).toUpperCase() + first.slice(1).toLowerCase();
};
